/*
 * Documentation-grade semantic C for the E15 FMV callback/consumer boundary.
 *
 * This is not a matching-source claim.  Exact function bounds, pristine slice
 * hashes, call sites, argument opcodes, return continuations and teardown/error
 * branches are regenerated by tools/phase4_fmv_interface_frontier.py.
 */
#include <stdint.h>

typedef void (*fmv_stream_callback)(void);

enum {
    CD_MODE_STREAM = 0x1c0,
    CD_COMMAND_SETMODE = 0x0e,
    CD_COMMAND_READS = 0x1b,
    CD_COMMAND_STOP = 0x08,
    CD_COMMAND_PAUSE = 0x0b,
};

#define CD_READY_SLOT          (*(fmv_stream_callback *)0x800818C8u)
#define STR_FRAME_READY_SLOT   (*(fmv_stream_callback *)0x800910F0u)
#define STR_SECTOR_READY_SLOT  (*(fmv_stream_callback *)0x800910F4u)
#define STR_BACKLOC            (*(uint32_t *)0x80088FFCu)
#define FMV_DECODE_STOP_LATCH  (*(volatile uint8_t *)0x800B9A54u)
#define FMV_COMPLETION_REQUEST (*(volatile uint32_t *)0x800CAC10u)

/* E15 player setup, expressed as the exact observable interface.  The ring
 * buffer has 32 records.  StSetStream receives (mode_is_3, 1, 0x0fffffff,
 * NULL, 0), which proves that the optional STR callback slot is disabled for
 * this player.  CdRead2(0x1c0) then installs the fixed handlers below. */
extern void StSetRing(void *ring, int count);
extern void StSetStream(int mode, int a1, int a2,
                        fmv_stream_callback callback, int arg5);
extern int CdRead2(int mode);
extern void StClearRing(void);
extern void clear_cd_stream_callbacks(void);
extern void str_data_ready_callback(void); /* 0x80070A30 */
extern void str_ready_wrapper(void);       /* 0x8007092C -> 0x80070D80 */

static void e15_stream_setup(void *ring, int display_mode)
{
    StSetRing(ring, 32);
    StSetStream(display_mode == 3, 1, 0x0fffffff, 0, 0);
    while (!CdRead2(CD_MODE_STREAM)) {
        /* Retail retries until libcd accepts the streamed read. */
    }
}

static void e15_stream_teardown(void)
{
    StClearRing();
    clear_cd_stream_callbacks();
}

/* Current same-anchor runtime control (external receipt bytes remain outside
 * Git): Start-only playback reaches StClearRing from 0x800B749C and then
 * clear_cd_stream_callbacks from 0x800B74A4 at emulator frame 4671.  The
 * 541-frame no-input control reaches neither call and retains exact FMV.BIN.
 * Function tracing labels the observed callback-clear exit a synthetic unwind,
 * while pristine guest bytes have a balanced ra/sp epilogue and return to
 * 0x800B74AC.  The four words captured at 0x80081C28 are the immutable
 * 0x1F801800..0x1F801803 CD-ROM MMIO pointer table, not callback storage.
 * Equality across endpoints therefore cannot falsify the byte stores through
 * cells 0x80081C28/0x80081C34 to registers 0/3.  These exact interface facts do
 * not turn one runtime path into an all-lifecycle claim. */

/* Callback chain:
 *   CdRead2 -> CdDataCallback(str_data_ready_callback)
 *           -> CdReadyCallback(str_ready_wrapper)
 *   str_ready_wrapper -> StCdInterrupt
 *   StCdInterrupt -> str_data_ready_callback
 * The data-ready handler updates STR_BACKLOC and would call STR_FRAME_READY_SLOT
 * at 0x80070AA0 only when non-NULL.  StCdInterrupt independently tests
 * STR_SECTOR_READY_SLOT before guarded calls at 0x800712DC and 0x80071388.
 * StSetStream loads its fifth stack argument at 0x80070B38 and stores it to the
 * second slot at 0x80070B88.  E15 supplies NULL for both slots.
 * Callback teardown runs in a critical section, clears both installed
 * callbacks, then writes zero to CD-ROM MMIO registers 0 and 3 through the
 * resident pointer cells before the transient FMV overlay and its allocations
 * retire. */

/* fmv_bin_load(selector, hook_enabled) is synchronous.  Its complete direct
 * resident consumer set has nine calls: boot dlogo/title/intro, bonus clip,
 * game-over lose, LEV15C finale, completed level B, LEV15D completion, and
 * level-A reset handoff.  hook_enabled is 0 or -1; it is passed as a value to
 * fixed pre/post transition routines and is not itself called.  Return sites
 * continue into shell, scene-flow, completion, or gameplay-reset ownership.
 * The three boot returns at 0x8004FB64/70/7C stay inside the exact
 * 0x8004FA40..0x8004FC3C main-shell owner.  Its guarded jr at 0x8004FC34
 * dispatches through six entries at 0x8001B3C4.  Targets 0x8004FC3C/50/64/78/8C
 * store destination indexes 1/11/2/7/12 (scenes 1/12/3/4/13) and join at
 * 0x8004FCC0; target 0x8004FCA0 resets the shell substate and invokes
 * 0x8005222C(1).  The five 20-byte target fragments and the 0x8004FCA0 owner
 * are separate hash-pinned ASM partitions, not part of the 508-byte main-shell
 * source.
 * The level-A return at 0x8005B790 remains inside the full
 * 0x8005B714..0x8005BC64 reset owner.  Its continuation includes the exact
 * scene-load call 0x8005B7CC -> 0x8003F358 and 19 further direct calls covering
 * display/loadscreen, resource, player/respawn/pool, scene and music reset.
 * All 20 post-FMV edges are exhaustively guarded; 0x8005B790 is not treated as
 * a function end.
 * A corrected recorded-anchor replay of the centrally pinned 15,230-frame
 * LEVEL01 movie now passively covers both the level-A call at 0x8005B788 and
 * completed-level-B call at 0x8005031C.  An all-neutral derivative covers
 * neither, and each coverage pass is RAM/register/cycle/frame neutral against
 * its own uninstrumented cached-interpreter control.  This is bounded positive
 * reachability: cumulative coverage does not identify the first call frame,
 * arguments, selector/limit, completion, or teardown for that route.
 * Movie-viewer/unlock policy is therefore outside this E15 interface and
 * remains owned by C17/E14 rather than being inferred from selector reachability.
 */

/* Statically bounded exceptional paths:
 *  - file-open failure prints the fixed diagnostic and continues initialization;
 *  - no decoded record sets FMV_DECODE_STOP_LATCH to one and returns -1;
 *  - decode polling has a finite 0x800000 budget and emits its timeout diagnostic;
 *  - GetlocP and CdRead2 submission retry until accepted;
 *  - frame-limit, decode-stop, resident-exit, input-sentinel, and completion
 *    exits all converge on the same callback/ring teardown frontier.
 * Runtime frequency and malformed-media policy are not claimed by static code.
 */
